import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Load Montserrat at module level to avoid flicker and ensure delayRender compliance
const { fontFamily: montserratFamily } = loadMontserrat("normal", {
  weights: ["400", "700", "900"],
});



export type SpiceMeterProps = Record<string, any>;

const SpiceMeter: React.FC<SpiceMeterProps> = ({
  backgroundColor = "#bd400a",
  transparentBackground = false,
  durationInSeconds = 6,
  targetSpiceLevel = 40,
  labelText = "HOT",
  showFlames = true,
  showSparks = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // 1. Calculations & Timing
  const totalFrames = durationInSeconds * fps;

  // Background color processing (handle transparency gracefully)
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Pepper Enter Animation (Spring)
  const scaleSpring = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  // Level fill animation (Starts at frame 15, completes smoothly)
  const levelSpring = spring({
    frame: frame - 15,
    fps,
    config: { damping: 18, stiffness: 60 },
  });

  // Interpolated percentage level
  const currentPercent = interpolate(levelSpring, [0, 1], [0, targetSpiceLevel], {
    extrapolateRight: "clamp",
  });

  // Rounded text percentage for countdown roll-up
  const textPercent = Math.round(currentPercent);

  // Shake / Vibration effect intensity based on spice level
  const isHighHeat = targetSpiceLevel >= 50;
  const shakeIntensity = isHighHeat ? interpolate(levelSpring, [0.5, 1], [0, 3]) : 0;
  const shakeX = shakeIntensity * Math.sin(frame * 0.9);
  const shakeY = shakeIntensity * Math.cos(frame * 0.8);

  // Text Animation
  const textSpring = spring({
    frame: frame - 22,
    fps,
    config: { damping: 12, stiffness: 90 },
  });
  const textX = interpolate(textSpring, [0, 1], [80, 0], { extrapolateRight: "clamp" });
  const textOpacity = interpolate(textSpring, [0, 1], [0, 1], { extrapolateRight: "clamp" });

  const labelSpring = spring({
    frame: frame - 28,
    fps,
    config: { damping: 12, stiffness: 90 },
  });
  const labelY = interpolate(labelSpring, [0, 1], [40, 0], { extrapolateRight: "clamp" });
  const labelOpacity = interpolate(labelSpring, [0, 1], [0, 1], { extrapolateRight: "clamp" });

  // Floating ambient wiggle calculations
  const floatOffset = Math.sin(frame * 0.05) * 6;

  // Meter visual heights
  // Top of pepper body is at y=180, bottom is at y=610. Span is 430 pixels.
  const topY = 180;
  const bottomY = 610;
  const totalSpan = bottomY - topY;
  const activeYThreshold = bottomY - (currentPercent / 100) * totalSpan;

  // Static/floating flame offsets for 1:1 match with storyboard design
  const bottomFlameWiggleX = Math.sin(frame * 0.08) * 4;
  const bottomFlameWiggleY = Math.cos(frame * 0.08) * 4;
  const topFlameWiggleX = Math.sin(frame * 0.08 + 3) * 5;
  const topFlameWiggleY = Math.cos(frame * 0.08 + 3) * 5;

  return (
    <AbsoluteFill
      style={{
        background: transparentBackground
          ? bgColor
          : `radial-gradient(circle, #e25816 0%, ${backgroundColor} 100%)`,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* 2. Spark/Ember Particle System (Floating behind & around pepper) */}
      {showSparks &&
        Array.from({ length: 18 }).map((_, i) => {
          const seedX = random(`ember-x-${i}`);
          const seedY = random(`ember-y-${i}`);
          const seedSpeed = random(`ember-speed-${i}`) * 1.8 + 0.8;
          const seedSize = random(`ember-size-${i}`) * 4 + 3;
          const startFrame = random(`ember-start-${i}`) * (totalFrames * 0.8);

          // Loop logic for continuous sparks
          const age = (frame - startFrame + totalFrames) % totalFrames;
          const progress = age / totalFrames;

          // Compute custom parabolic path drifting from bottom-left to top-right
          const opacity = interpolate(progress, [0, 0.15, 0.85, 1], [0, 0.9, 0.9, 0], {
            extrapolateRight: "clamp",
          });
          const xPos = interpolate(progress, [0, 1], [width * 0.18 + seedX * 80, width * 0.45 + seedX * 180]);
          const yPos = interpolate(progress, [0, 1], [height * 0.72 + seedY * 40, height * 0.15 - seedY * 120]);

          return (
            <div
              key={`ember-${i}`}
              style={{
                position: "absolute",
                left: xPos,
                top: yPos,
                width: seedSize,
                height: seedSize,
                borderRadius: "50%",
                backgroundColor: "#ffca28",
                boxShadow: "0 0 12px #ff6f00, 0 0 6px #ffffff",
                opacity,
                transform: `scale(${interpolate(progress, [0.8, 1], [1, 0], { extrapolateRight: "clamp" })})`,
                pointerEvents: "none",
                transition: "none",
              }}
            />
          );
        })}

      {/* 3. Static/Foreground Flames from Storyboard */}
      {showFlames && (
        <>
          {/* Flame 1: Bottom-Left of the Pepper */}
          <div
            style={{
              position: "absolute",
              left: width * 0.1,
              top: height * 0.63,
              width: width * 0.16,
              height: width * 0.16,
              transform: `translate(${bottomFlameWiggleX}px, ${bottomFlameWiggleY}px) scale(${interpolate(scaleSpring, [0, 1], [0, 1.1])})`,
              opacity: interpolate(levelSpring, [0.2, 0.8], [0.3, 1], { extrapolateRight: "clamp" }),
              transition: "none",
              pointerEvents: "none",
              zIndex: 1,
            }}
          >
            <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", overflow: "visible" }}>
              <defs>
                <linearGradient id="flameGrad1" x1="0%" y1="100%" x2="0%" y2="0%">
                  <stop offset="0%" stopColor="#f34225" />
                  <stop offset="50%" stopColor="#fdbc10" />
                  <stop offset="100%" stopColor="#ffeb3b" stopOpacity="0" />
                </linearGradient>
              </defs>
              <path
                d="M 50 95 C 20 95, 5 75, 15 50 C 10 25, 35 15, 45 40 C 42 20, 65 10, 70 35 C 80 50, 80 80, 50 95 Z"
                fill="url(#flameGrad1)"
                filter="drop-shadow(0px 4px 10px rgba(243, 66, 37, 0.6))"
              />
            </svg>
          </div>

          {/* Flame 2: Top-Right of the Text */}
          <div
            style={{
              position: "absolute",
              left: width * 0.72,
              top: height * 0.23,
              width: width * 0.15,
              height: width * 0.15,
              transform: `translate(${topFlameWiggleX}px, ${topFlameWiggleY}px) scale(${interpolate(labelSpring, [0, 1], [0, 1])})`,
              opacity: labelOpacity,
              transition: "none",
              pointerEvents: "none",
              zIndex: 1,
            }}
          >
            <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", overflow: "visible" }}>
              <path
                d="M 50 95 C 20 95, 10 75, 18 50 C 15 25, 40 15, 48 40 C 45 20, 68 10, 72 35 C 82 50, 80 80, 50 95 Z"
                fill="url(#flameGrad1)"
                filter="drop-shadow(0px 4px 10px rgba(243, 66, 37, 0.5))"
              />
            </svg>
          </div>
        </>
      )}

      {/* 4. Left Column: Chili Pepper */}
      <div
        style={{
          position: "absolute",
          left: width * 0.12,
          top: height * 0.1,
          width: width * 0.4,
          height: height * 0.8,
          transform: `scale(${scaleSpring}) translate(${shakeX}px, ${shakeY + floatOffset}px)`,
          filter: "drop-shadow(0px 20px 30px rgba(0,0,0,0.6))",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        <svg
          viewBox="0 0 300 700"
          style={{
            width: "100%",
            height: "100%",
            overflow: "visible",
          }}
        >
          <defs>
            {/* Soft Outer Golden Glow Filter */}
            <filter id="chiliGlow" x="-25%" y="-25%" width="150%" height="150%">
              <feGaussianBlur stdDeviation="15" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>

            {/* Clip path representing the exact curvy outline of the pepper body */}
            <clipPath id="chili-body-clip">
              <path d="M 130 180 C 100 250, 90 380, 140 500 C 170 560, 220 600, 270 610 C 230 580, 180 500, 175 400 C 170 310, 190 230, 210 180 C 180 183, 150 177, 130 180 Z" />
            </clipPath>
          </defs>

          {/* Underlay glow path */}
          <path
            d="M 130 180 C 100 250, 90 380, 140 500 C 170 560, 220 600, 270 610 C 230 580, 180 500, 175 400 C 170 310, 190 230, 210 180 C 180 183, 150 177, 130 180 Z"
            fill="none"
            stroke="#ffeb3b"
            strokeWidth="24"
            opacity={interpolate(levelSpring, [0.3, 1], [0.1, 0.65], { extrapolateRight: "clamp" })}
            filter="url(#chiliGlow)"
          />

          {/* Clean White Outer Border */}
          <path
            d="M 130 180 C 100 250, 90 380, 140 500 C 170 560, 220 600, 270 610 C 230 580, 180 500, 175 400 C 170 310, 190 230, 210 180 C 180 183, 150 177, 130 180 Z"
            fill="none"
            stroke="#ffffff"
            strokeWidth="10"
            strokeLinejoin="round"
          />

          {/* Clipped Segmented Body Content */}
          <g clipPath="url(#chili-body-clip)">
            {/* Color Zone 1 (Bottom Green) */}
            <rect x="0" y="524" width="300" height="90" fill="#4ba520" />
            {/* Color Zone 2 (Yellow-Green) */}
            <rect x="0" y="438" width="300" height="86" fill="#a2ce39" />
            {/* Color Zone 3 (Yellow) */}
            <rect x="0" y="352" width="300" height="86" fill="#ffeb3b" />
            {/* Color Zone 4 (Orange) */}
            <rect x="0" y="266" width="300" height="86" fill="#fdbc10" />
            {/* Color Zone 5 (Top Red) */}
            <rect x="0" y="150" width="300" height="116" fill="#f34225" />

            {/* Dark sliding overlay to represent the "unlit" segments */}
            <rect
              x="0"
              y="180"
              width="300"
              height={activeYThreshold - 180}
              fill="#181818"
              opacity="0.82"
              style={{ transition: "none" }}
            />

            {/* Soft interior highlight gradient line overlay */}
            <path
              d="M 140 180 C 110 250, 100 380, 150 500"
              fill="none"
              stroke="#ffffff"
              strokeWidth="6"
              opacity="0.25"
            />

            {/* Stylized Curved Segment Dividers (matching storyboard curve) */}
            <path d="M 50 518 Q 150 538, 250 518" fill="none" stroke="#ffffff" strokeWidth="3" opacity="0.4" />
            <path d="M 50 432 Q 150 452, 250 432" fill="none" stroke="#ffffff" strokeWidth="3" opacity="0.4" />
            <path d="M 50 346 Q 150 366, 250 346" fill="none" stroke="#ffffff" strokeWidth="3" opacity="0.4" />
            <path d="M 50 260 Q 150 280, 250 260" fill="none" stroke="#ffffff" strokeWidth="3" opacity="0.4" />
          </g>

          {/* Green Stem/Cap - Sits neatly on top of the red body */}
          <path
            d="M 125 180
               C 135 167, 145 183, 155 174
               C 165 183, 175 167, 185 174
               C 195 183, 205 167, 215 180
               C 210 160, 195 110, 185 80
               C 180 60, 185 30, 195 15
               C 185 25, 168 65, 168 95
               C 168 125, 168 155, 125 180 Z"
            fill="#529916"
            stroke="#ffffff"
            strokeWidth="8"
            strokeLinejoin="round"
          />
        </svg>
      </div>

      {/* 5. Right Column: Metric Label & Percentage */}
      <div
        style={{
          position: "absolute",
          left: width * 0.48,
          top: height * 0.35,
          width: width * 0.45,
          height: height * 0.45,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "flex-start",
          fontFamily: montserratFamily,
          color: "#ffffff",
          textShadow: "0px 8px 24px rgba(0,0,0,0.5)",
          transform: `translate(${shakeX * 0.4}px, ${shakeY * 0.4}px)`,
          transition: "none",
        }}
      >
        {/* Dynamic Percentage value */}
        <div
          style={{
            fontSize: Math.min(width, height) * 0.165,
            fontWeight: 900,
            lineHeight: 0.85,
            opacity: textOpacity,
            transform: `translateX(${textX}px)`,
            transition: "none",
          }}
        >
          {textPercent}%
        </div>

        {/* Dynamic Label Text */}
        <div
          style={{
            fontSize: Math.min(width, height) * 0.115,
            fontWeight: 900,
            lineHeight: 0.95,
            letterSpacing: "2px",
            opacity: labelOpacity,
            transform: `translateY(${labelY}px)`,
            transition: "none",
          }}
        >
          {labelText}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SpiceMeter;